-- J-LAS Flashcard community fixtures, MySQL 8.0.21+, UTF-8.
-- GENERATED by tools/flashcard_seed/build_seed.py from data/flashcard/*.json. Do not edit this output.
-- SYNTHETIC DEMO DATA: learner accounts, public sets, studies, ratings, favorites and comments are fictional.
-- These are development/demo fixtures, NOT genuine learner activity or public endorsements.
-- Do not import on production to manufacture ratings or testimonials.
-- Vocabulary: vocabulary_entry BOTH/PUBLISHED (JMdict, CC BY-SA 4.0) x OpenJLPT N5-N4 levels, and
-- TEXTBOOK/PUBLISHED (reviewed Sekai N5-N4 lessons). TEXTBOOK/DRAFT (unreviewed) is never used.
-- Learner accounts come from tools/demo_learners.py, shared with the Shadowing interaction seed:
-- name-based @gmail.com addresses, no password, unverified; an existing login-capable account with
-- the same email aborts the import. Earlier .invalid demo accounts are renamed in place.
-- No fixed database IDs, passwords, credit grants, notifications or emails sent.
-- Idempotent: a set whose owner already has a live set with the same title is left untouched
-- (cards, ratings and comments included), so reruns and user edits are preserved.
-- Older demo seeds' public sets (owner @flashcard_legacy_owner_email, default demo@jlab.local): titles and
-- descriptions still carrying a card count are renamed, missing Hán Việt is filled, and learner activity
-- is added once (only while no demo learner has activity on that set and it is at least a day old).
-- {{SET_COUNT}} public sets / {{CARD_COUNT}} cards / {{LEARNER_COUNT}} learners / {{VOTE_COUNT}} ratings /
-- {{FAVORITE_COUNT}} favorites / {{SESSION_COUNT}} completed studies / {{COMMENT_COUNT}} rated comments
-- (incl. {{LEGACY_SET_COUNT}} older demo sets; {{LEGACY_HAN_VIET_COUNT}} Hán Việt values for their cards).

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
SET @flashcard_community_payload = {{PAYLOAD}};

DROP PROCEDURE IF EXISTS jlas_seed_flashcard_community_v1;
DELIMITER $$
CREATE PROCEDURE jlas_seed_flashcard_community_v1()
SQL SECURITY INVOKER
BEGIN
    DECLARE locked INT DEFAULT 0;
    DECLARE started INT DEFAULT 0;
    DECLARE learner_role BIGINT UNSIGNED;
    DECLARE anchor_time DATETIME(6);
    DECLARE lock_name VARCHAR(64);
    DECLARE new_sets INT DEFAULT 0;
    DECLARE legacy_owner VARCHAR(255);
    DECLARE legacy_found INT DEFAULT 0;
    DECLARE legacy_active INT DEFAULT 0;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        IF started = 1 THEN ROLLBACK; END IF;
        IF locked = 1 THEN DO RELEASE_LOCK(lock_name); END IF;
        RESIGNAL;
    END;
    IF DATABASE() IS NULL OR @@autocommit <> 1 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Select a DEMO database in a fresh autocommit connection';
    END IF;
    IF (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE()
        AND table_name IN ('roles','users','flashcard_set','flashcard_card','flashcard_user_set_state',
                          'flashcard_study_session','content_comment','content_comment_rating') AND engine='InnoDB') <> 8 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Current Flashcard schema with InnoDB tables is required';
    END IF;
    SELECT id INTO learner_role FROM roles WHERE name='LEARNER';
    IF learner_role IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'The LEARNER role is required';
    END IF;
    SET lock_name=CONCAT('jlas-flashcard-community-',LEFT(SHA2(DATABASE(),256),30));
    SELECT GET_LOCK(lock_name,10) INTO locked;
    IF COALESCE(locked,0) <> 1 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Another Flashcard community seed import is running';
    END IF;
    START TRANSACTION;
    SET started=1;
    SET anchor_time=CURRENT_TIMESTAMP(6)-INTERVAL 1 HOUR;

    -- Shared demo learners (same identities and rules as the Shadowing interaction seed).
    CREATE TEMPORARY TABLE fc_user (
        user_key VARCHAR(20) PRIMARY KEY, full_name VARCHAR(150) NOT NULL,
        email VARCHAR(255) NOT NULL UNIQUE, username VARCHAR(50) NOT NULL UNIQUE,
        legacy_email VARCHAR(255) NOT NULL UNIQUE, legacy_username VARCHAR(50) NOT NULL UNIQUE,
        level_code VARCHAR(10) NOT NULL, user_id BIGINT UNSIGNED NULL
    ) ENGINE=InnoDB;
    INSERT INTO fc_user SELECT j.*,NULL FROM JSON_TABLE(@flashcard_community_payload,'$.learners[*]' COLUMNS (
        user_key VARCHAR(20) PATH '$.key',full_name VARCHAR(150) PATH '$.name',email VARCHAR(255) PATH '$.email',
        username VARCHAR(50) PATH '$.username',legacy_email VARCHAR(255) PATH '$.legacy_email',
        legacy_username VARCHAR(50) PATH '$.legacy_username',level_code VARCHAR(10) PATH '$.level')) j;
    UPDATE users u JOIN fc_user d ON u.email=d.legacy_email AND COALESCE(u.username,'')=d.legacy_username
    LEFT JOIN users taken ON taken.email=d.email OR taken.username=d.username
    SET u.email=d.email,u.username=d.username
    WHERE taken.id IS NULL AND u.role_id=learner_role AND u.password_hash IS NULL AND u.google_id IS NULL
      AND u.is_verified=0 AND u.login_type='LOCAL';
    -- Demo identities must never be adopted from an actual login-capable account.
    IF EXISTS (SELECT 1 FROM fc_user d JOIN users u ON u.email=d.email OR u.username=d.username
               WHERE u.email<>d.email OR COALESCE(u.username,'')<>d.username OR u.role_id<>learner_role
                  OR u.password_hash IS NOT NULL OR u.google_id IS NOT NULL OR u.is_verified<>0 OR u.login_type<>'LOCAL') THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Demo identity collision; existing account will not be modified';
    END IF;
    INSERT INTO users(role_id,email,username,password_hash,login_type,full_name,japanese_level,is_verified,created_at,updated_at)
    SELECT learner_role,d.email,d.username,NULL,'LOCAL',d.full_name,d.level_code,0,
           anchor_time-INTERVAL 120 DAY,anchor_time-INTERVAL 120 DAY
    FROM fc_user d LEFT JOIN users u ON u.email=d.email WHERE u.id IS NULL;
    UPDATE fc_user d JOIN users u ON u.email=d.email SET d.user_id=u.id;

    CREATE TEMPORARY TABLE fc_set (
        set_key VARCHAR(40) PRIMARY KEY, owner_key VARCHAR(20) NOT NULL, title VARCHAR(100) NOT NULL,
        description VARCHAR(500) NULL, age_days INT UNSIGNED NOT NULL,
        owner_id BIGINT UNSIGNED NULL, created_at DATETIME(6) NULL, span_sec BIGINT NULL,
        is_new TINYINT NOT NULL DEFAULT 0, set_id BIGINT UNSIGNED NULL
    ) ENGINE=InnoDB;
    INSERT INTO fc_set(set_key,owner_key,title,description,age_days)
    SELECT * FROM JSON_TABLE(@flashcard_community_payload,'$.sets[*]' COLUMNS (
        set_key VARCHAR(40) PATH '$.key',owner_key VARCHAR(20) PATH '$.owner_key',title VARCHAR(100) PATH '$.title',
        description VARCHAR(500) PATH '$.description',age_days INT UNSIGNED PATH '$.age_days')) j;
    -- A set is never older than its owner's account; activity is spread over [created_at, anchor].
    UPDATE fc_set d JOIN fc_user o ON o.user_key=d.owner_key JOIN users u ON u.id=o.user_id
    SET d.owner_id=u.id,
        d.created_at=GREATEST(u.created_at+INTERVAL 1 DAY,anchor_time-INTERVAL d.age_days DAY);
    IF EXISTS (SELECT 1 FROM fc_set WHERE created_at>=anchor_time-INTERVAL 1 DAY) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Demo owner accounts are too new for the set timeline; import aborted';
    END IF;
    UPDATE fc_set SET span_sec=TIMESTAMPDIFF(SECOND,created_at,anchor_time);
    UPDATE fc_set d SET d.is_new=1
    WHERE NOT EXISTS (SELECT 1 FROM flashcard_set s WHERE s.owner_id=d.owner_id AND s.title=d.title AND s.deleted_at IS NULL);
    SELECT COUNT(*) INTO new_sets FROM fc_set WHERE is_new=1;
    INSERT INTO flashcard_set(owner_id,folder_id,title,description,visibility,is_draft,moderation_status,
                              moderation_checked_at,created_at,updated_at)
    SELECT d.owner_id,NULL,d.title,d.description,'PUBLIC',0,'SAFE',d.created_at,d.created_at,d.created_at
    FROM fc_set d WHERE d.is_new=1 ORDER BY d.created_at,d.set_key;
    UPDATE fc_set d JOIN flashcard_set s ON s.owner_id=d.owner_id AND s.title=d.title AND s.deleted_at IS NULL
        AND s.created_at=d.created_at
    SET d.set_id=s.id WHERE d.is_new=1;

    -- Public sets of the older demo seeds.
    SET legacy_owner=COALESCE(NULLIF(TRIM(@flashcard_legacy_owner_email),''),
                              JSON_UNQUOTE(JSON_EXTRACT(@flashcard_community_payload,'$.legacy_owner')));
    CREATE TEMPORARY TABLE fc_legacy (
        set_key VARCHAR(40) PRIMARY KEY, title VARCHAR(100) NOT NULL, description VARCHAR(500) NULL,
        set_id BIGINT UNSIGNED NULL, created_at DATETIME(6) NULL, span_sec BIGINT NULL,
        needs_activity TINYINT NOT NULL DEFAULT 0
    ) ENGINE=InnoDB;
    INSERT INTO fc_legacy(set_key,title,description)
    SELECT * FROM JSON_TABLE(@flashcard_community_payload,'$.legacy_sets[*]' COLUMNS (
        set_key VARCHAR(40) PATH '$.key',title VARCHAR(100) PATH '$.title',
        description VARCHAR(500) PATH '$.description')) j;
    CREATE TEMPORARY TABLE fc_legacy_title (
        set_key VARCHAR(40) NOT NULL, title VARCHAR(100) COLLATE utf8mb4_bin NOT NULL, PRIMARY KEY(set_key,title)
    ) ENGINE=InnoDB;
    INSERT INTO fc_legacy_title SELECT * FROM JSON_TABLE(@flashcard_community_payload,'$.legacy_titles[*]' COLUMNS (
        set_key VARCHAR(40) PATH '$.set_key',title VARCHAR(100) PATH '$.title')) j;
    CREATE TEMPORARY TABLE fc_legacy_description (
        set_key VARCHAR(40) NOT NULL, description VARCHAR(500) COLLATE utf8mb4_bin NOT NULL
    ) ENGINE=InnoDB;
    INSERT INTO fc_legacy_description SELECT * FROM JSON_TABLE(@flashcard_community_payload,'$.legacy_descriptions[*]' COLUMNS (
        set_key VARCHAR(40) PATH '$.set_key',description VARCHAR(500) PATH '$.description')) j;
    UPDATE fc_legacy l SET l.set_id=(
        SELECT MIN(s.id) FROM flashcard_set s JOIN users o ON o.id=s.owner_id
        JOIN fc_legacy_title t ON t.set_key=l.set_key AND t.title=s.title COLLATE utf8mb4_bin
        WHERE o.email=legacy_owner AND s.visibility='PUBLIC' AND s.is_draft=0 AND s.deleted_at IS NULL);
    SELECT COUNT(set_id) INTO legacy_found FROM fc_legacy;
    -- Rename only titles/descriptions that still equal a known seeded value; user edits are kept.
    UPDATE flashcard_set s JOIN fc_legacy l ON l.set_id=s.id
    JOIN fc_legacy_title t ON t.set_key=l.set_key AND t.title=s.title COLLATE utf8mb4_bin
    SET s.title=l.title WHERE s.title COLLATE utf8mb4_bin<>l.title;
    UPDATE flashcard_set s JOIN fc_legacy l ON l.set_id=s.id
    JOIN fc_legacy_description x ON x.set_key=l.set_key AND x.description=s.description COLLATE utf8mb4_bin
    SET s.description=l.description;
    CREATE TEMPORARY TABLE fc_han_viet (
        front VARCHAR(500) COLLATE utf8mb4_bin PRIMARY KEY, han_viet VARCHAR(255) NOT NULL
    ) ENGINE=InnoDB;
    INSERT INTO fc_han_viet SELECT * FROM JSON_TABLE(@flashcard_community_payload,'$.legacy_han_viet[*]' COLUMNS (
        front VARCHAR(500) PATH '$.front',han_viet VARCHAR(255) PATH '$.han_viet')) j;
    UPDATE flashcard_card c JOIN fc_legacy l ON l.set_id=c.set_id
    JOIN fc_han_viet h ON h.front=c.front COLLATE utf8mb4_bin
    SET c.han_viet=h.han_viet WHERE c.han_viet IS NULL OR TRIM(c.han_viet)='';
    -- Activity starts after both the set and the demo accounts exist.
    UPDATE fc_legacy l JOIN flashcard_set s ON s.id=l.set_id
    SET l.created_at=GREATEST(s.created_at,(SELECT MAX(u.created_at) FROM users u JOIN fc_user f ON f.user_id=u.id));
    UPDATE fc_legacy SET span_sec=TIMESTAMPDIFF(SECOND,created_at,anchor_time) WHERE set_id IS NOT NULL;
    UPDATE fc_legacy l SET l.needs_activity=1
    WHERE l.set_id IS NOT NULL AND l.span_sec>=86400
      -- MySQL opens a temporary table once per statement, so fc_user appears in a single subquery.
      AND NOT EXISTS (SELECT 1 FROM fc_user f
                      WHERE EXISTS (SELECT 1 FROM flashcard_user_set_state x WHERE x.set_id=l.set_id AND x.user_id=f.user_id)
                         OR EXISTS (SELECT 1 FROM flashcard_study_session x WHERE x.set_id=l.set_id AND x.user_id=f.user_id));
    SELECT COUNT(*) INTO legacy_active FROM fc_legacy WHERE needs_activity=1;

    CREATE TEMPORARY TABLE fc_card (
        set_key VARCHAR(40) NOT NULL, position INT UNSIGNED NOT NULL, front VARCHAR(500) NOT NULL,
        back VARCHAR(500) NOT NULL, reading VARCHAR(255) NULL, meaning VARCHAR(500) NOT NULL,
        han_viet VARCHAR(255) NULL, jlpt_level VARCHAR(10) NOT NULL, word_type VARCHAR(50) NULL,
        example_ja TEXT NULL, example_vi TEXT NULL, PRIMARY KEY(set_key,position)
    ) ENGINE=InnoDB;
    INSERT INTO fc_card SELECT * FROM JSON_TABLE(@flashcard_community_payload,'$.cards[*]' COLUMNS (
        set_key VARCHAR(40) PATH '$.set_key',position INT UNSIGNED PATH '$.position',front VARCHAR(500) PATH '$.front',
        back VARCHAR(500) PATH '$.back',reading VARCHAR(255) PATH '$.reading',meaning VARCHAR(500) PATH '$.meaning',
        han_viet VARCHAR(255) PATH '$.han_viet',jlpt_level VARCHAR(10) PATH '$.jlpt_level',
        word_type VARCHAR(50) PATH '$.word_type',example_ja TEXT PATH '$.example_ja',example_vi TEXT PATH '$.example_vi')) j;
    INSERT INTO flashcard_card(set_id,front,back,reading,meaning,han_viet,jlpt_level,word_type,
                               example_ja,example_vi,position,created_at,updated_at)
    SELECT d.set_id,c.front,c.back,c.reading,c.meaning,c.han_viet,c.jlpt_level,c.word_type,
           c.example_ja,c.example_vi,c.position,d.created_at,d.created_at
    FROM fc_card c JOIN fc_set d USING(set_key) WHERE d.is_new=1;

    -- Sets that receive seeded activity in this run: new community sets and untouched legacy sets.
    CREATE TEMPORARY TABLE fc_target (
        set_key VARCHAR(40) PRIMARY KEY, set_id BIGINT UNSIGNED NOT NULL,
        created_at DATETIME(6) NOT NULL, span_sec BIGINT NOT NULL
    ) ENGINE=InnoDB;
    INSERT INTO fc_target SELECT set_key,set_id,created_at,span_sec FROM fc_set WHERE is_new=1;
    INSERT INTO fc_target SELECT set_key,set_id,created_at,span_sec FROM fc_legacy WHERE needs_activity=1;

    CREATE TEMPORARY TABLE fc_state (
        set_key VARCHAR(40) NOT NULL, user_key VARCHAR(20) NOT NULL, rating TINYINT UNSIGNED NULL,
        favorite TINYINT NOT NULL, first_permille SMALLINT UNSIGNED NOT NULL, last_permille SMALLINT UNSIGNED NOT NULL,
        PRIMARY KEY(set_key,user_key)
    ) ENGINE=InnoDB;
    INSERT INTO fc_state SELECT * FROM JSON_TABLE(@flashcard_community_payload,'$.states[*]' COLUMNS (
        set_key VARCHAR(40) PATH '$.set_key',user_key VARCHAR(20) PATH '$.user_key',
        rating TINYINT UNSIGNED PATH '$.rating' NULL ON EMPTY,favorite TINYINT PATH '$.favorite',
        first_permille SMALLINT UNSIGNED PATH '$.first_permille',last_permille SMALLINT UNSIGNED PATH '$.last_permille')) j;
    INSERT INTO flashcard_user_set_state(user_id,set_id,is_favorite,rating,first_completed_at,last_accessed_at,updated_at)
    SELECT u.user_id,d.set_id,s.favorite,s.rating,
           TIMESTAMPADD(SECOND,d.span_sec*s.first_permille DIV 1000,d.created_at),
           TIMESTAMPADD(SECOND,d.span_sec*s.last_permille DIV 1000,d.created_at),
           TIMESTAMPADD(SECOND,d.span_sec*s.last_permille DIV 1000,d.created_at)
    FROM fc_state s JOIN fc_target d USING(set_key) JOIN fc_user u USING(user_key);

    CREATE TEMPORARY TABLE fc_session (
        set_key VARCHAR(40) NOT NULL, user_key VARCHAR(20) NOT NULL, seq TINYINT UNSIGNED NOT NULL,
        permille SMALLINT UNSIGNED NOT NULL, seconds INT UNSIGNED NOT NULL, PRIMARY KEY(set_key,user_key,seq)
    ) ENGINE=InnoDB;
    INSERT INTO fc_session SELECT * FROM JSON_TABLE(@flashcard_community_payload,'$.sessions[*]' COLUMNS (
        set_key VARCHAR(40) PATH '$.set_key',user_key VARCHAR(20) PATH '$.user_key',seq TINYINT UNSIGNED PATH '$.seq',
        permille SMALLINT UNSIGNED PATH '$.permille',seconds INT UNSIGNED PATH '$.seconds')) j;
    INSERT INTO flashcard_study_session(user_id,set_id,session_type,mode,status,started_at,finished_at)
    SELECT u.user_id,d.set_id,'FLASHCARD','ALL','COMPLETED',
           GREATEST(d.created_at,TIMESTAMPADD(SECOND,d.span_sec*s.permille DIV 1000-s.seconds,d.created_at)),
           TIMESTAMPADD(SECOND,d.span_sec*s.permille DIV 1000,d.created_at)
    FROM fc_session s JOIN fc_target d USING(set_key) JOIN fc_user u USING(user_key)
    ORDER BY d.set_key,u.user_id,s.seq;

    CREATE TEMPORARY TABLE fc_comment (
        set_key VARCHAR(40) NOT NULL, comment_key VARCHAR(60) NOT NULL, user_key VARCHAR(20) NOT NULL,
        content TEXT NOT NULL, rating TINYINT UNSIGNED NOT NULL, permille SMALLINT UNSIGNED NOT NULL,
        PRIMARY KEY(set_key,comment_key)
    ) ENGINE=InnoDB;
    INSERT INTO fc_comment SELECT * FROM JSON_TABLE(@flashcard_community_payload,'$.comments[*]' COLUMNS (
        set_key VARCHAR(40) PATH '$.set_key',comment_key VARCHAR(60) PATH '$.key',user_key VARCHAR(20) PATH '$.user_key',
        content TEXT PATH '$.content',rating TINYINT UNSIGNED PATH '$.rating',permille SMALLINT UNSIGNED PATH '$.permille')) j;
    INSERT INTO content_comment(target_type,target_id,user_id,content,is_hidden,created_at,updated_at)
    SELECT 'FLASHCARD_SET',d.set_id,u.user_id,c.content,0,
           TIMESTAMPADD(SECOND,d.span_sec*c.permille DIV 1000,d.created_at),
           TIMESTAMPADD(SECOND,d.span_sec*c.permille DIV 1000,d.created_at)
    FROM fc_comment c JOIN fc_target d USING(set_key) JOIN fc_user u USING(user_key)
    ORDER BY d.set_key,c.permille;
    INSERT INTO content_comment_rating(comment_id,rating,created_at)
    SELECT cc.id,c.rating,cc.created_at
    FROM fc_comment c JOIN fc_target d USING(set_key) JOIN fc_user u USING(user_key)
    JOIN content_comment cc ON cc.target_type='FLASHCARD_SET' AND cc.target_id=d.set_id AND cc.user_id=u.user_id
        AND BINARY cc.content=BINARY c.content
    WHERE NOT EXISTS (SELECT 1 FROM content_comment_rating r WHERE r.comment_id=cc.id);

    COMMIT;
    SET started=0;
    DO RELEASE_LOCK(lock_name);
    SET locked=0;
    SELECT 'SYNTHETIC_DEMO' data_kind,(SELECT COUNT(*) FROM fc_user) demo_learners,
           (SELECT COUNT(*) FROM fc_set) sets_in_payload,new_sets inserted_sets,
           legacy_found legacy_sets_found,legacy_active legacy_sets_given_activity;
    SELECT s.id,s.title,u.full_name owner,
           (SELECT COUNT(*) FROM flashcard_card c WHERE c.set_id=s.id) cards,
           (SELECT COUNT(*) FROM flashcard_user_set_state x WHERE x.set_id=s.id AND x.rating IS NOT NULL) rating_count,
           (SELECT ROUND(AVG(x.rating),2) FROM flashcard_user_set_state x WHERE x.set_id=s.id) avg_rating,
           (SELECT COUNT(*) FROM flashcard_user_set_state x WHERE x.set_id=s.id AND x.is_favorite=1) favorites,
           (SELECT COUNT(*) FROM flashcard_study_session x WHERE x.set_id=s.id AND x.status='COMPLETED') studies,
           (SELECT COUNT(*) FROM content_comment x WHERE x.target_type='FLASHCARD_SET' AND x.target_id=s.id) comments
    FROM (SELECT s.id FROM fc_set d JOIN flashcard_set s ON s.owner_id=d.owner_id AND s.title=d.title
              AND s.deleted_at IS NULL
          UNION SELECT set_id FROM fc_legacy WHERE set_id IS NOT NULL) ids
    JOIN flashcard_set s ON s.id=ids.id JOIN users u ON u.id=s.owner_id
    ORDER BY s.id;
END$$
DELIMITER ;
CALL jlas_seed_flashcard_community_v1();
DROP PROCEDURE jlas_seed_flashcard_community_v1;
